from decimal import Decimal, getcontext, ROUND_HALF_UP, InvalidOperation

getcontext().prec = 80

_Q2 = Decimal("0.01")

# Contenido de LS_PARAMETROS segun 02_parametros.sql. Solo se usa cuando la
# entrada "params" NO viene informada (vacia/ausente). Si "params" viene
# informado, se interpreta como el contenido completo de LS_PARAMETROS: un
# codigo ausente provoca ORA-20010 (fn_param_num, lineas 98-112).
_DEFAULT_PARAMS = {
    "DIAS_MAX_DENUNCIA": "30",
    "DIAS_MAX_DENUNCIA_VIDA": "365",
    "DEDUCIBLE_MINIMO": "100",
    "PCT_DESCUENTO_DED_VIP": "50",
    "TOLERANCIA_MORA_VIP": "500",
    "MAX_SINIESTROS_ANUAL": "3",
    "PCT_PENALIZACION_SINIEST": "10",
    "UMBRAL_RETENCION": "10000",
    "TASA_RETENCION": "2",
    "TOPE_AUTO_APROBACION": "50000",
    "DIAS_ALERTA_FRAUDE": "15",
    "PCT_ALERTA_FRAUDE": "80",
    "FACTOR_INFLACION": "1.035",
    "TASA_IVA": "19",
    "VERSION_MOTOR": None,
}

_NULL = object()


class _OraError(Exception):
    def __init__(self, code, message):
        Exception.__init__(self, message)
        self.code = code
        self.message = message


def _clean(value):
    return str(value).strip().strip('"').strip("'").strip()


def _dec(value, default="0"):
    if value is None:
        return Decimal(default)
    s = _clean(value)
    if s == "" or s.lower() in ("null", "none"):
        return Decimal(default)
    try:
        return Decimal(s)
    except InvalidOperation:
        return Decimal(default)


def _num142(value):
    # Asignacion a NUMBER(14,2): redondeo mitad hacia arriba a 2 decimales.
    if value is None:
        return None
    return Decimal(value).quantize(_Q2, rounding=ROUND_HALF_UP)


def _round2(value):
    # ROUND(x, 2) de Oracle.
    if value is None:
        return None
    return Decimal(value).quantize(_Q2, rounding=ROUND_HALF_UP)


def _fmt2(value):
    d = _num142(value)
    if d is None or d == 0:
        d = Decimal("0.00")
    return format(d, "f")


# Semantica NULL de Oracle: cualquier comparacion con NULL es falsa y
# cualquier aritmetica con NULL devuelve NULL.
def _gt(a, b):
    return a is not None and b is not None and a > b


def _ge(a, b):
    return a is not None and b is not None and a >= b


def _lt(a, b):
    return a is not None and b is not None and a < b


def _le(a, b):
    return a is not None and b is not None and a <= b


def _mul(a, b):
    return None if a is None or b is None else a * b


def _sub(a, b):
    return None if a is None or b is None else a - b


def _div(a, b):
    return None if a is None or b is None else a / b


def _parse_bool(value):
    if isinstance(value, bool):
        return value
    s = _clean(value).upper()
    return s in ("TRUE", "T", "1", "S", "SI", "Y", "YES")


def _days_from_civil(y, m, d):
    y -= 1 if m <= 2 else 0
    era = (y if y >= 0 else y - 399) // 400
    yoe = y - era * 400
    mp = (m + 9) % 12
    doy = (153 * mp + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468


def _date_ord(value):
    # TRUNC(fecha): solo la parte YYYY-MM-DD.
    s = _clean(value)[:10]
    parts = s.split("-")
    return _days_from_civil(int(parts[0]), int(parts[1]), int(parts[2]))


def _parse_params(raw):
    # Devuelve dict codigo -> texto del valor (o _NULL si valor_numerico NULL).
    if raw is None:
        return dict(_DEFAULT_PARAMS)
    if isinstance(raw, dict):
        if not raw:
            return dict(_DEFAULT_PARAMS)
        result = {}
        for k, v in raw.items():
            result[str(k).strip().upper()] = v
        return result
    s = str(raw).strip()
    if s == "" or s.lower() in ("null", "none", "{}"):
        return dict(_DEFAULT_PARAMS)
    if s.startswith("{"):
        s = s[1:]
    if s.endswith("}"):
        s = s[:-1]
    s = s.replace("\n", ",").replace(";", ",")
    result = {}
    for item in s.split(","):
        item = item.strip()
        if not item:
            continue
        sep = None
        for cand in (":", "="):
            if cand in item:
                sep = cand
                break
        if sep is None:
            continue
        k, v = item.split(sep, 1)
        k = _clean(k).upper()
        v = _clean(v)
        if k:
            result[k] = v
    return result


def _add_obs(obs, mark):
    # PR_AGREGAR_OBS
    if obs is None or obs == "":
        return mark
    return obs + ";" + mark


def _error(code, message):
    return {
        "status": "ERROR",
        "reason_code": code,
        "base_amount": "0.00",
        "deductible_amount": "0.00",
        "covered_amount": "0.00",
        "withholding_amount": "0.00",
        "net_amount": "0.00",
        "observations": message,
    }


def _liquidar(inp):
    params = _parse_params(inp.get("params"))

    def p(code):
        # FN_PARAM_NUM (lineas 98-112)
        if code not in params:
            raise _OraError("ORA-20010", "Parametro no definido: " + code)
        v = params.get(code)
        if v is None:
            return None
        s = _clean(v)
        if s == "" or s.lower() in ("null", "none"):
            return None
        try:
            return Decimal(s)
        except InvalidOperation:
            return None

    claimed = _num142(_dec(inp.get("claimed_amount")))
    occ = _date_ord(inp.get("occurrence_date"))
    rep = _date_ord(inp.get("report_date"))
    pol_status = _clean(inp.get("policy_status", ""))
    pol_start = _date_ord(inp.get("policy_start_date"))
    pol_end = _date_ord(inp.get("policy_end_date"))
    ramo = _clean(inp.get("line_of_business", ""))
    sum_insured = _num142(_dec(inp.get("sum_insured")))
    ded_type = _clean(inp.get("deductible_type", ""))
    ded_value = _num142(_dec(inp.get("deductible_value")))
    pending_premium = _num142(_dec(inp.get("pending_premium")))
    category = _clean(inp.get("customer_category", ""))
    coverage_found = _parse_bool(inp.get("coverage_found", "false"))
    cov_limit = _num142(_dec(inp.get("coverage_limit")))
    cov_pct = _dec(inp.get("coverage_pct")).quantize(_Q2, rounding=ROUND_HALF_UP)
    waiting_days = _dec(inp.get("waiting_days"))
    prior_count = _dec(inp.get("prior_liquidated_claims_365d"))
    total_indemnified = _dec(inp.get("total_indemnified"))

    def register(status, reason, base, ded, cov, ret, net, obs):
        # PR_REGISTRAR_RESULTADO: columnas de importes NOT NULL.
        for val in (base, ded, cov, ret, net):
            if val is None:
                raise _OraError("ORA-01400",
                                "cannot insert NULL into LS_LIQUIDACIONES")
        return {
            "status": status,
            "reason_code": reason,
            "base_amount": _fmt2(base),
            "deductible_amount": _fmt2(ded),
            "covered_amount": _fmt2(cov),
            "withholding_amount": _fmt2(ret),
            "net_amount": _fmt2(net),
            "observations": obs if obs else "",
        }

    def reject(reason, obs=None):
        # PR_RECHAZAR: importes en 0
        z = Decimal("0")
        return register("RECHAZADA", reason, z, z, z, z, z, obs)

    observations = None

    # Linea 375: lectura incondicional de FACTOR_INFLACION (ORA-20010 si falta)
    p("FACTOR_INFLACION")

    # 1.a Estado de la poliza (linea 386)
    if pol_status != "VIGENTE":
        return reject("POLIZA_NO_VIGENTE")

    # 1.b Vigencia, extremos inclusive (lineas 395-400)
    if occ < pol_start or occ > pol_end:
        return reject("FUERA_DE_VIGENCIA")

    # 1.c Plazo de denuncia (lineas 407-418)
    dias_denuncia = Decimal(rep - occ)
    if ramo == "VIDA":
        dias_max = p("DIAS_MAX_DENUNCIA_VIDA")
    else:
        dias_max = p("DIAS_MAX_DENUNCIA")
    if _gt(dias_denuncia, dias_max):
        return reject("DENUNCIA_EXTEMPORANEA")

    # 1.d Cobertura contratada (lineas 423-433)
    if not coverage_found:
        return reject("COBERTURA_NO_CONTRATADA")

    # 1.e Carencia (lineas 440-445)
    dias_desde_inicio = Decimal(occ - pol_start)
    if dias_desde_inicio < waiting_days:
        return reject("EN_PERIODO_CARENCIA")

    # 1.f Morosidad (lineas 451-462)
    if pending_premium > 0:
        tolerancia = p("TOLERANCIA_MORA_VIP")
        if category == "VIP" and _le(pending_premium, tolerancia):
            observations = _add_obs(observations, "TOLERANCIA_MORA_VIP")
        else:
            return reject("PRIMA_EN_MORA", observations)

    # 2.a Monto base (lineas 487-492)
    if claimed > cov_limit:
        base = _num142(cov_limit)
        observations = _add_obs(observations, "LIMITE_COBERTURA")
    else:
        base = _num142(claimed)

    # 2.b Deducible (fn_calcular_deducible, lineas 179-208)
    if ded_type == "FIJO":
        deductible = _num142(ded_value)
    else:
        ded_min = p("DEDUCIBLE_MINIMO")
        deductible = _num142(_round2(base * ded_value / Decimal(100)))
        if _lt(deductible, ded_min):
            deductible = _num142(ded_min)
            observations = _add_obs(observations, "DEDUCIBLE_MINIMO")
    if category == "VIP" and _gt(deductible, Decimal(0)):
        pct_vip = p("PCT_DESCUENTO_DED_VIP")
        deductible = _num142(_round2(_div(_mul(deductible, _sub(Decimal(100), pct_vip)), Decimal(100))))
        observations = _add_obs(observations, "DESCUENTO_VIP")

    # 2.c Monto cubierto (lineas 503-508)
    covered = _num142(_round2(_div(_mul(_sub(base, deductible), cov_pct), Decimal(100))))
    if _le(covered, Decimal(0)):
        return reject("BAJO_DEDUCIBLE", observations)

    # 2.d Siniestralidad (lineas 521-533)
    if _ge(prior_count, p("MAX_SINIESTROS_ANUAL")):
        pct_pen = p("PCT_PENALIZACION_SINIEST")
        covered = _num142(_round2(_div(_mul(covered, _sub(Decimal(100), pct_pen)), Decimal(100))))
        observations = _add_obs(observations, "PENALIZACION_SINIESTRALIDAD")

    # 2.e Suma asegurada remanente (lineas 541-558)
    remanente = sum_insured - total_indemnified
    if remanente <= 0:
        return reject("SUMA_ASEGURADA_AGOTADA", observations)
    if _gt(covered, remanente):
        covered = _num142(remanente)
        observations = _add_obs(observations, "TOPE_SUMA_ASEGURADA")

    # 2.f Retencion y neto (lineas 565-574); AND con cortocircuito
    if ramo != "VIDA" and _gt(covered, p("UMBRAL_RETENCION")):
        withholding = _num142(_round2(_div(_mul(covered, p("TASA_RETENCION")), Decimal(100))))
        observations = _add_obs(observations, "RETENCION_APLICADA")
    else:
        withholding = Decimal("0.00")
    net = _num142(_sub(covered, withholding))

    # 3. Estado final (lineas 586-599); fraude con prioridad
    umbral_fraude = _round2(_div(_mul(cov_limit, p("PCT_ALERTA_FRAUDE")), Decimal(100)))
    dias_alerta = p("DIAS_ALERTA_FRAUDE")
    if _le(dias_desde_inicio, dias_alerta) and _ge(claimed, umbral_fraude):
        status = "PENDIENTE_APROBACION"
        reason = "SOSPECHA_FRAUDE"
    elif _gt(net, p("TOPE_AUTO_APROBACION")):
        status = "PENDIENTE_APROBACION"
        reason = "SUPERA_TOPE_AUTOMATICO"
    else:
        status = "APROBADA"
        reason = "LIQUIDACION_AUTOMATICA"

    return register(status, reason, base, deductible, covered, withholding, net, observations)


def run(inp: dict) -> dict:
    try:
        return _liquidar(inp)
    except _OraError as e:
        return _error(e.code, e.message)
